void R2V_5(const double M, const double r0,
    const vector<double> &r_grid, const vector<double> &f_grid, const vector<double> &fp_grid,
    const ModeBlock &h1, const ModeBlock &dh1, const ModeBlock &ddh1,
    const ModeBlock &h2, const ModeBlock &dh2, const ModeBlock &ddh2,
    int l1, int m1, int l2, int m2, double *const *Gr, double *const *Gi, size_t jb, size_t je)
{
  (void) fp_grid;
  R2V_5_impl<double>(M, r0, r_grid.data(), f_grid.data(), h1, dh1, ddh1, h2, dh2, ddh2, l1, m1, l2, m2, Gr, Gi, jb, je);
}

void R2V_5(const double M, const double r0, const Taylor3 *r, const Taylor3 *f,
    const ModeBlockT<Taylor3> &h1, const ModeBlockT<Taylor3> &dh1, const ModeBlockT<Taylor3> &ddh1,
    const ModeBlockT<Taylor3> &h2, const ModeBlockT<Taylor3> &dh2, const ModeBlockT<Taylor3> &ddh2,
    int l1, int m1, int l2, int m2, Taylor3 *const *Gr, Taylor3 *const *Gi)
{
  R2V_5_impl<Taylor3>(M, r0, r, f, h1, dh1, ddh1, h2, dh2, ddh2, l1, m1, l2, m2, Gr, Gi, 0, 1);
}

